//! `nam_remote_simd_receipt` — Automated Audit Receipt Generator for Remote SIMD Gates (T4.1.1).
//!
//! Processes Criterion benchmark outputs (`target/criterion/`) generated by `isa_compare_bench.rs`,
//! evaluates AVX2 vs AVX-512 speedup against the $\ge 12\%$ ROI threshold ($p < 0.05$),
//! probes host hardware and toolchain metadata, and emits a structured JSON audit receipt
//! (`target/logs/remote-simd-receipt.json`) along with a formatted Markdown audit table.
//!
//! # Usage
//! ```sh
//! cargo run --features testing --bin nam_remote_simd_receipt -- [--criterion-dir <DIR>] [--out <FILE>] [--json | --table] [--check]
//! ```
//!
//! # Exit Codes
//! - 0: Gate passed or report generated successfully.
//! - 1: Gate violation (speedup < 12% or p >= 0.05 on canonical SKU, or runtime failure).
//! - 2: Usage / command-line argument error.

use std::env;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::exit;

use serde::{Deserialize, Serialize};
use serde_json::Value;

use neural_amp_modeler_rs::testing::qa::env::EnvProbe;

/// Primary ROI speedup threshold for canonical SKUs at N=64.
pub const PRIMARY_SPEEDUP_THRESHOLD_PCT: f64 = 12.0;
/// Primary statistical significance alpha level (p < 0.05).
pub const STATISTICAL_ALPHA: f64 = 0.05;
/// Smoke regression threshold for low-buffer sizes (N=1, 8).
pub const SMOKE_REGRESSION_THRESHOLD_PCT: f64 = 0.0;

/// Canonical SKU benchmark definition.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CanonicalSkuDef {
    /// Canonical SKU identifier.
    pub sku_id: &'static str,
    /// Criterion group name prefix in `isa_compare_bench.rs`.
    pub criterion_prefix: &'static str,
}

/// The 5 canonical SKUs tested in `isa_compare_bench.rs`.
pub const CANONICAL_SKUS: [CanonicalSkuDef; 5] = [
    CanonicalSkuDef {
        sku_id: "LSTM_2x16",
        criterion_prefix: "ISA_Compare_LSTM_2x16",
    },
    CanonicalSkuDef {
        sku_id: "LSTM_1x16",
        criterion_prefix: "ISA_Compare_LSTM_1x16",
    },
    CanonicalSkuDef {
        sku_id: "A2Full_CH8",
        criterion_prefix: "ISA_Compare_A2Full_CH8",
    },
    CanonicalSkuDef {
        sku_id: "A2Lite_CH3",
        criterion_prefix: "ISA_Compare_A2Lite_CH3",
    },
    CanonicalSkuDef {
        sku_id: "WaveNet_Standard_CH16",
        criterion_prefix: "ISA_Compare_WaveNet_Std_CH16",
    },
];

/// The buffer sizes evaluated in the canonical matrix.
pub const BUFFER_SIZES: [usize; 3] = [64, 8, 1];

/// Environment metadata included in the receipt.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct EnvironmentReceipt {
    pub cpu_model: String,
    pub effective_isa: String,
    pub physical_cores: u32,
    pub logical_cores: u32,
    pub frequency_mhz: String,
    pub kernel_version: String,
    pub rustc_version: String,
    pub host_triple: String,
    pub git_commit: String,
    pub git_dirty: bool,
}

/// Evaluation result for a single SKU and buffer size combination.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct SkuBenchmarkResult {
    pub sku: String,
    pub criterion_group: String,
    pub buffer_size: usize,
    pub avx2_mean_us: Option<f64>,
    pub avx512_mean_us: Option<f64>,
    pub speedup_pct: Option<f64>,
    pub p_value: Option<f64>,
    pub threshold_pct: f64,
    pub verdict: String,
    pub notes: String,
}

/// Gate policy configuration recorded in receipt.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct GatePolicy {
    pub primary_threshold_pct: f64,
    pub primary_block_size: usize,
    pub p_value_alpha: f64,
    pub smoke_regression_threshold_pct: f64,
}

/// Full Remote SIMD Gate Audit Receipt schema.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq)]
pub struct RemoteSimdReceipt {
    pub schema_version: String,
    pub generated_at_utc: String,
    pub environment: EnvironmentReceipt,
    pub gate_policy: GatePolicy,
    pub overall_verdict: String,
    pub results: Vec<SkuBenchmarkResult>,
}

/// Summary statistics extracted from Criterion output.
#[derive(Debug, Clone)]
pub struct SampleStats {
    pub mean_ns: f64,
    pub std_dev_ns: f64,
    pub sample_count: usize,
    pub variance_ns2: f64,
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut criterion_dir = PathBuf::from("target/criterion");
    let mut out_path = PathBuf::from("target/logs/remote-simd-receipt.json");
    let mut format_json_stdout = false;
    let mut format_table = true;
    let mut enforce_check = false;

    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--criterion-dir" => {
                if i + 1 < args.len() {
                    criterion_dir = PathBuf::from(&args[i + 1]);
                    i += 1;
                } else {
                    eprintln!("Error: --criterion-dir requires a directory path");
                    exit(2);
                }
            }
            "--out" => {
                if i + 1 < args.len() {
                    out_path = PathBuf::from(&args[i + 1]);
                    i += 1;
                } else {
                    eprintln!("Error: --out requires a file path");
                    exit(2);
                }
            }
            "--json" => {
                format_json_stdout = true;
                format_table = false;
            }
            "--table" => {
                format_table = true;
            }
            "--check" => {
                enforce_check = true;
            }
            "--help" | "-h" => {
                print_help();
                exit(0);
            }
            arg => {
                eprintln!("Unknown argument: {arg}");
                print_help();
                exit(2);
            }
        }
        i += 1;
    }

    let receipt = build_receipt(&criterion_dir);

    // Ensure output directory exists
    if let Some(parent) = out_path.parent() {
        let _ = fs::create_dir_all(parent);
    }

    let json_text = serde_json::to_string_pretty(&receipt).unwrap_or_default();
    if let Err(e) = fs::write(&out_path, &json_text) {
        eprintln!(
            "Warning: Failed to write receipt to {}: {}",
            out_path.display(),
            e
        );
    }

    if format_json_stdout {
        println!("{json_text}");
    } else if format_table {
        render_audit_table(&receipt, &out_path);
    }

    if enforce_check && receipt.overall_verdict != "PASS" {
        exit(1);
    }
}

fn print_help() {
    println!("NeuralAmpModeler-rs Remote SIMD Receipt Generator");
    println!("Usage: nam_remote_simd_receipt [OPTIONS]");
    println!();
    println!("Options:");
    println!(
        "  --criterion-dir <DIR> Path to Criterion benchmark outputs (default: target/criterion)"
    );
    println!(
        "  --out <FILE>          Destination file for receipt JSON (default: target/logs/remote-simd-receipt.json)"
    );
    println!("  --table               Display formatted Markdown table (default)");
    println!("  --json                Emit formatted JSON to stdout");
    println!("  --check               Exit with status 1 if overall verdict is not PASS");
    println!("  --help, -h            Show this help message");
}

/// Builds the full `RemoteSimdReceipt` from the environment and Criterion files.
pub fn build_receipt(criterion_dir: &Path) -> RemoteSimdReceipt {
    let probe = EnvProbe::probe();
    let logical_cores = num_cpus();
    let frequency_mhz = probe_cpu_frequency();
    let kernel_version = probe_kernel_version();
    let timestamp_utc = utc_timestamp_iso8601();

    let env_receipt = EnvironmentReceipt {
        cpu_model: probe.cpu_model,
        effective_isa: probe.effective_isa.to_string(),
        physical_cores: probe.physical_cores,
        logical_cores,
        frequency_mhz,
        kernel_version,
        rustc_version: probe.rustc_version,
        host_triple: probe.host_triple,
        git_commit: probe.git_commit,
        git_dirty: probe.git_dirty,
    };

    let gate_policy = GatePolicy {
        primary_threshold_pct: PRIMARY_SPEEDUP_THRESHOLD_PCT,
        primary_block_size: 64,
        p_value_alpha: STATISTICAL_ALPHA,
        smoke_regression_threshold_pct: SMOKE_REGRESSION_THRESHOLD_PCT,
    };

    let mut results = Vec::new();
    let mut all_primary_passed = true;
    let mut any_measured = false;
    let mut any_missing_avx512 = false;

    for sku in &CANONICAL_SKUS {
        for &size in &BUFFER_SIZES {
            let group_name = format!("{}_{size}samp_48kHz", sku.criterion_prefix);
            let group_dir = criterion_dir.join(&group_name);

            let avx2_dir = group_dir.join("AVX2");
            let avx512_dir = group_dir.join("AVX512");

            let avx2_stats = read_benchmark_stats(&avx2_dir);
            let avx512_stats = read_benchmark_stats(&avx512_dir);

            let is_primary = size == 64;
            let threshold_pct = if is_primary {
                PRIMARY_SPEEDUP_THRESHOLD_PCT
            } else {
                SMOKE_REGRESSION_THRESHOLD_PCT
            };

            let (avx2_mean_us, avx512_mean_us, speedup_pct, p_val, verdict, notes) =
                match (avx2_stats, avx512_stats) {
                    (Some(s2), Some(s512)) => {
                        any_measured = true;
                        let u2 = s2.mean_ns / 1000.0;
                        let u512 = s512.mean_ns / 1000.0;
                        let delta_pct = if u2 > 0.0 {
                            ((u2 - u512) / u2) * 100.0
                        } else {
                            0.0
                        };

                        let p = welch_t_test_p_value(&s2, &s512);

                        let passed = if is_primary {
                            delta_pct >= PRIMARY_SPEEDUP_THRESHOLD_PCT && p < STATISTICAL_ALPHA
                        } else {
                            delta_pct >= SMOKE_REGRESSION_THRESHOLD_PCT
                        };

                        if !passed {
                            all_primary_passed = false;
                        }

                        let v = if passed { "PASS" } else { "FAIL" };
                        let note = if is_primary {
                            format!(
                                "Speedup: {:.2}%, p={:.4} (req >= {:.1}%, p < {:.2})",
                                delta_pct, p, PRIMARY_SPEEDUP_THRESHOLD_PCT, STATISTICAL_ALPHA
                            )
                        } else {
                            format!("Smoke N={}: {:.2}% vs AVX2", size, delta_pct)
                        };

                        (
                            Some(u2),
                            Some(u512),
                            Some(delta_pct),
                            Some(p),
                            v.to_string(),
                            note,
                        )
                    }
                    (Some(s2), None) => {
                        any_missing_avx512 = true;
                        let u2 = s2.mean_ns / 1000.0;
                        (
                            Some(u2),
                            None,
                            None,
                            None,
                            "SKIPPED".to_string(),
                            "AVX-512 benchmark arm not executed (hardware missing or skipped)"
                                .to_string(),
                        )
                    }
                    (None, Some(s512)) => {
                        let u512 = s512.mean_ns / 1000.0;
                        all_primary_passed = false;
                        (
                            None,
                            Some(u512),
                            None,
                            None,
                            "MISSING_BASELINE".to_string(),
                            "AVX2 baseline benchmark missing".to_string(),
                        )
                    }
                    (None, None) => {
                        any_missing_avx512 = true;
                        (
                            None,
                            None,
                            None,
                            None,
                            "NOT_RUN".to_string(),
                            "Benchmark data not found in criterion directory".to_string(),
                        )
                    }
                };

            results.push(SkuBenchmarkResult {
                sku: sku.sku_id.to_string(),
                criterion_group: group_name,
                buffer_size: size,
                avx2_mean_us,
                avx512_mean_us,
                speedup_pct,
                p_value: p_val,
                threshold_pct,
                verdict,
                notes,
            });
        }
    }

    let overall_verdict = if any_measured && all_primary_passed {
        "PASS".to_string()
    } else if any_missing_avx512 && !any_measured {
        "SKIPPED_NO_AVX512".to_string()
    } else {
        "FAIL".to_string()
    };

    RemoteSimdReceipt {
        schema_version: "1.0".to_string(),
        generated_at_utc: timestamp_utc,
        environment: env_receipt,
        gate_policy,
        overall_verdict,
        results,
    }
}

/// Reads Criterion sample or estimate files from a benchmark arm directory.
fn read_benchmark_stats(arm_dir: &Path) -> Option<SampleStats> {
    // Prefer new/sample.json or sample.json for exact sample series
    let sample_paths = [arm_dir.join("new/sample.json"), arm_dir.join("sample.json")];
    for path in &sample_paths {
        if let Ok(content) = fs::read_to_string(path)
            && let Some(stats) = parse_sample_json(&content)
        {
            return Some(stats);
        }
    }

    // Fallback to estimates.json
    let estimate_paths = [
        arm_dir.join("new/estimates.json"),
        arm_dir.join("estimates.json"),
    ];
    for path in &estimate_paths {
        if let Ok(content) = fs::read_to_string(path)
            && let Some(stats) = parse_estimates_json(&content)
        {
            return Some(stats);
        }
    }

    None
}

/// Parses Criterion `sample.json` to calculate mean, sample variance, and size.
pub fn parse_sample_json(json_str: &str) -> Option<SampleStats> {
    let val: Value = serde_json::from_str(json_str).ok()?;
    let iters = val.get("iters")?.as_array()?;
    let times = val.get("times")?.as_array()?;

    if iters.is_empty() || iters.len() != times.len() {
        return None;
    }

    let n = iters.len();
    let mut measurements = Vec::with_capacity(n);
    let mut sum = 0.0;

    for (iter_val, time_val) in iters.iter().zip(times.iter()) {
        let it = iter_val.as_f64()?;
        let tm = time_val.as_f64()?;
        if it <= 0.0 {
            return None;
        }
        let per_iter_ns = tm / it;
        measurements.push(per_iter_ns);
        sum += per_iter_ns;
    }

    let mean = sum / (n as f64);
    let mut var_sum = 0.0;
    for &m in &measurements {
        let diff = m - mean;
        var_sum += diff * diff;
    }

    let variance = if n > 1 {
        var_sum / ((n - 1) as f64)
    } else {
        0.0
    };
    let std_dev = variance.sqrt();

    Some(SampleStats {
        mean_ns: mean,
        std_dev_ns: std_dev,
        sample_count: n,
        variance_ns2: variance,
    })
}

/// Parses Criterion `estimates.json` as fallback.
pub fn parse_estimates_json(json_str: &str) -> Option<SampleStats> {
    let val: Value = serde_json::from_str(json_str).ok()?;
    let mean_val = val.get("mean")?.get("point_estimate")?.as_f64()?;
    let std_dev = val
        .get("std_dev")?
        .get("point_estimate")?
        .as_f64()
        .unwrap_or(0.0);
    let variance = std_dev * std_dev;

    Some(SampleStats {
        mean_ns: mean_val,
        std_dev_ns: std_dev,
        sample_count: 50,
        variance_ns2: variance,
    })
}

/// Computes Welch's unequal variance two-sample t-test two-tailed p-value.
pub fn welch_t_test_p_value(s1: &SampleStats, s2: &SampleStats) -> f64 {
    let n1 = s1.sample_count as f64;
    let n2 = s2.sample_count as f64;

    if n1 <= 1.0 || n2 <= 1.0 {
        return 1.0;
    }

    let v1 = s1.variance_ns2 / n1;
    let v2 = s2.variance_ns2 / n2;
    let se = (v1 + v2).sqrt();

    if se <= 1e-18 {
        return if (s1.mean_ns - s2.mean_ns).abs() < 1e-12 {
            1.0
        } else {
            0.0
        };
    }

    let t = (s1.mean_ns - s2.mean_ns).abs() / se;

    // Welch-Satterthwaite degrees of freedom
    let num = (v1 + v2) * (v1 + v2);
    let den = (v1 * v1) / (n1 - 1.0) + (v2 * v2) / (n2 - 1.0);
    let df = if den > 0.0 { num / den } else { 1.0 };

    student_t_two_tailed_p_value(t, df)
}

/// Computes two-tailed p-value for Student's t distribution with `df` degrees of freedom.
pub fn student_t_two_tailed_p_value(t: f64, df: f64) -> f64 {
    if df <= 0.0 {
        return 1.0;
    }
    let x = df / (df + t * t);
    let a = df / 2.0;
    let b = 0.5;

    regularized_incomplete_beta(x, a, b).clamp(0.0, 1.0)
}

/// Regularized incomplete beta function I_x(a, b).
pub fn regularized_incomplete_beta(x: f64, a: f64, b: f64) -> f64 {
    if x <= 0.0 {
        return 0.0;
    }
    if x >= 1.0 {
        return 1.0;
    }

    let bt = if x == 0.0 || x == 1.0 {
        0.0
    } else {
        let ln_beta = ln_gamma(a) + ln_gamma(b) - ln_gamma(a + b);
        (a * x.ln() + b * (1.0 - x).ln() - ln_beta).exp()
    };

    if x < (a + 1.0) / (a + b + 2.0) {
        bt * betacf(a, b, x) / a
    } else {
        1.0 - bt * betacf(b, a, 1.0 - x) / b
    }
}

/// Continued fraction for incomplete beta function (Numerical Recipes betacf).
fn betacf(a: f64, b: f64, x: f64) -> f64 {
    const MAXIT: usize = 100;
    const EPS: f64 = 1.0e-12;
    const FPMIN: f64 = 1.0e-30;

    let qab = a + b;
    let qap = a + 1.0;
    let qam = a - 1.0;

    let mut c = 1.0f64;
    let mut d = 1.0f64 - qab * x / qap;
    if d.abs() < FPMIN {
        d = FPMIN;
    }
    d = 1.0 / d;
    let mut h = d;

    for m in 1..=MAXIT {
        let m_f = m as f64;
        let m2 = 2.0 * m_f;

        // Even step
        let aa = m_f * (b - m_f) * x / ((qam + m2) * (a + m2));
        d = 1.0 + aa * d;
        if d.abs() < FPMIN {
            d = FPMIN;
        }
        c = 1.0 + aa / c;
        if c.abs() < FPMIN {
            c = FPMIN;
        }
        d = 1.0 / d;
        h *= d * c;

        // Odd step
        let aa = -(a + m_f) * (qab + m_f) * x / ((a + m2) * (qap + m2));
        d = 1.0 + aa * d;
        if d.abs() < FPMIN {
            d = FPMIN;
        }
        c = 1.0 + aa / c;
        if c.abs() < FPMIN {
            c = FPMIN;
        }
        d = 1.0 / d;
        let del = d * c;
        h *= del;

        if (del - 1.0).abs() < EPS {
            break;
        }
    }

    h
}

/// Natural log of the gamma function using standard Lanczos approximation (g=7, N=9).
pub fn ln_gamma(z: f64) -> f64 {
    if z <= 0.0 {
        return 0.0;
    }
    let p = [
        0.999_999_999_999_809_9,
        676.5203681218851,
        -1259.1392167224028,
        771.323_428_777_653_1,
        -176.615_029_162_140_6,
        12.507343278686905,
        -0.138571095856205,
        9.984_369_578_019_572e-6,
        1.5056327351493116e-7,
    ];
    let g = 7.0;
    let x = z - 1.0;
    let mut ag = p[0];
    for (i, &pi) in p.iter().enumerate().skip(1) {
        ag += pi / (x + i as f64);
    }
    let t = x + g + 0.5;
    0.5 * (2.0 * std::f64::consts::PI).ln() + (x + 0.5) * t.ln() - t + ag.ln()
}

/// Probe logical CPU count.
fn num_cpus() -> u32 {
    let output = std::process::Command::new("nproc").output();
    if let Ok(out) = output
        && let Ok(text) = String::from_utf8(out.stdout)
        && let Ok(num) = text.trim().parse::<u32>()
    {
        return num;
    }
    1
}

/// Probe CPU frequency in MHz.
fn probe_cpu_frequency() -> String {
    if let Ok(text) = fs::read_to_string("/sys/devices/system/cpu/cpu0/cpufreq/scaling_cur_freq")
        && let Ok(khz) = text.trim().parse::<f64>()
    {
        return format!("{:.1}", khz / 1000.0);
    }
    if let Ok(text) = fs::read_to_string("/proc/cpuinfo") {
        for line in text.lines() {
            if line.starts_with("cpu MHz")
                && let Some((_, val)) = line.split_once(':')
            {
                return val.trim().to_string();
            }
        }
    }
    "unknown".to_string()
}

/// Probe Linux kernel release string.
fn probe_kernel_version() -> String {
    let output = std::process::Command::new("uname").arg("-r").output();
    if let Ok(out) = output
        && let Ok(text) = String::from_utf8(out.stdout)
    {
        let trimmed = text.trim();
        if !trimmed.is_empty() {
            return trimmed.to_string();
        }
    }
    "unknown".to_string()
}

/// Generate UTC ISO-8601 formatted timestamp string.
fn utc_timestamp_iso8601() -> String {
    let output = std::process::Command::new("date")
        .args(["-u", "+%Y-%m-%dT%H:%M:%SZ"])
        .output();
    if let Ok(out) = output
        && let Ok(text) = String::from_utf8(out.stdout)
    {
        let trimmed = text.trim();
        if !trimmed.is_empty() {
            return trimmed.to_string();
        }
    }
    "1970-01-01T00:00:00Z".to_string()
}

/// Prints a formatted audit table to stdout.
fn render_audit_table(receipt: &RemoteSimdReceipt, out_path: &Path) {
    println!();
    println!("================================================================================");
    println!("            NEURALAMPMODELER-RS REMOTE SIMD GATE AUDIT RECEIPT                  ");
    println!("================================================================================");
    println!("Generated:        {}", receipt.generated_at_utc);
    println!(
        "Host CPU:         {} ({} physical cores, {} threads)",
        receipt.environment.cpu_model,
        receipt.environment.physical_cores,
        receipt.environment.logical_cores
    );
    println!("Detected ISA:     {}", receipt.environment.effective_isa);
    println!(
        "Kernel / rustc:   {} / {}",
        receipt.environment.kernel_version, receipt.environment.rustc_version
    );
    println!(
        "Git Commit:       {}{}",
        receipt.environment.git_commit,
        if receipt.environment.git_dirty {
            " (dirty)"
        } else {
            ""
        }
    );
    println!("Receipt Location: {}", out_path.display());
    println!("Overall Verdict:  {}", receipt.overall_verdict);
    println!("--------------------------------------------------------------------------------");
    println!(
        "{:<24} | {:>4} | {:>10} | {:>10} | {:>10} | {:>8} | {:>7}",
        "SKU ID", "N", "AVX2 (us)", "AVX512(us)", "Speedup", "p-value", "Verdict"
    );
    println!(
        "-------------------------+------+------------+------------+------------+----------+--------"
    );

    for r in &receipt.results {
        let avx2_str = r
            .avx2_mean_us
            .map(|v| format!("{:.2}", v))
            .unwrap_or_else(|| "-".to_string());
        let avx512_str = r
            .avx512_mean_us
            .map(|v| format!("{:.2}", v))
            .unwrap_or_else(|| "-".to_string());
        let speedup_str = r
            .speedup_pct
            .map(|v| format!("{:.2}%", v))
            .unwrap_or_else(|| "-".to_string());
        let p_str = r
            .p_value
            .map(|v| format!("{:.4}", v))
            .unwrap_or_else(|| "-".to_string());

        println!(
            "{:<24} | {:>4} | {:>10} | {:>10} | {:>10} | {:>8} | {:>7}",
            r.sku, r.buffer_size, avx2_str, avx512_str, speedup_str, p_str, r.verdict
        );
    }
    println!("================================================================================");
}

